float smin( float a, float b, float k )
{
float h = clamp(0.5 + 0.5*(b-a)/k, 0.0 , 1.0 );
return mix(b, a, h) - k*h*(1.0 - h);
}
vec2 GetDist(vec3 p)
{
float groundDist = p.y;
float groundID = 1;
// torus 1
vec3 torusPosNew = RotY(p - torus1Pos, uTime);
vec3 pNew = RotY(p, q26*1.5);
float torusDist = sdTorus1(pNew - torus1Pos, torus1Size);
float torusID = 2;
// torus 2
//float torus2Dist = sdTorus2(p - torus2Pos, torus2Size);
//float torus2ID = 2.1;
// sphere
float sphereDist = sdSphere(p - spherePos, sphereRad);
float sphereID = 3;
float shape = min(groundDist, torusDist);
//shape = min(shape, torus2Dist);
shape = min(shape, sphereDist);
vec2 toreturn;
if(shape == groundDist)
toreturn = vec2(groundDist, groundID);
if(shape == torusDist)
toreturn = vec2(torusDist, torusID);
if(shape == sphereDist)
toreturn = vec2(sphereDist, sphereID);
return toreturn;
}
vec3 RayMarch(vec3 ro, vec3 rd, float steps)
{
vec2 dS;
float dO;
vec3 p;
float breakloop = 0;
for(int i = 0; i<steps && breakloop == 0; i++)
{
p = ro + rd * dO;
dS = GetDist(p);
if(dS.x < 0.0001) {breakloop = 1; }
dO += dS.x*0.5;
}
return vec3(dO,dS);
}
float dist(vec2 a, vec2 b)
{
return sqrt(pow(a.x-b.x, 2.0 ) + pow(a.y-b.y, 2.0 ));
}
float fract(float a)
{
return(a - floor(a));
}
vec2 fract(vec2 a)
{
vec2 b = vec2(fract(a.x), fract(a.y));
return b;
}
float Hash21(vec2 p)
{
p = fract(p * vec2(234.34, 435.345) );
p += dot(p, p + 34.24);
return fract(p.x*p.y);
}
