float r = 0.51 + 0.5*sin(dist - 5.0*q26 - 0.0*0.2*q6 - uTime * 1.0);
float c = smoothstep(r, r*0.05, d);
m = m*(1.0 - c) + c*(1.0 - m);
}
}
//col.xy = gv.xy;
//col += vec3(m, 0.0 ,m*0.5);
