}
vec3 toruscol(vec3 p, vec3 tpos, vec2 tsize, float rotspeed)
{
//vec3 col = 0;
float x = atan(p.x + tpos.x, p.z + tpos.z);
float y = atan(length(p.xz + tpos.xz)-tsize.x, p.y + tpos.y);
