//float f1 = sin(x * 25.0)*sin(y * 50.0+speed);
//f1 = smoothstep( 0.0 , 0.001, f1);
float f1 = smoothstep(0.4, 0.5, 0.5 + 0.5*cos(y*(30.0 * sin(q26*0.5)) + x*(15 + 0*5*sin(uTime*0.5 + q6*0.05))));
//            * smoothstep( 0.0 , 0.5, sin(y*(55 + 35.0 * sin(q26)) + uTime * 20.0*0 + q26 * 40.0 + 0.0 * q5*2.5));
float f2 = smoothstep(0.4, 0.5, 0.5 + 0.5*sin(y*(30.0 * cos(q26*0.5)) + x*(15 + 0*5*cos(uTime*0.5 + q6*0.05))));
vec3 col1 = f1*f2*vec3(1 + 60.0 * q2, 1.0 , 1.0 );
vec3 col2 = f1*f2*vec3(1 + 60.0 * q2, 1.0 , 1.0 );
return col1; // + SpaceGif(abs(vec2(x,y)) * 10.0);
}
vec3 GetNormal(vec3 p)
{
float d = GetDist(p).x;
vec2 e = vec2(.01, 0.0 );
vec3 n = d-vec3(GetDist(p-e.xyy).x,
GetDist(p-e.yxy).x,
GetDist(p-e.yyx).x);
return normalize(n);
}
