float x = length(p.xz + GetShapes(p) )-r.x;
return q14*(length(vec2(x, p.y + (q2*0.12)*sin(10.0 * p.x + 10.0*p.z + uTime * 10.0)))-r.y);
}
float sdTorus2(vec3 p, vec2 r) {
float x = length(p.xz+(q27*0.05)*sin(7.0 * p.zx +uTime * 20.0*0 + 0.0 * q26 * 5.0))-r.x;
return q14*(length(vec2(x, p.y))-r.y);
}
float sdSphere( vec3 p, float s )
{
return length(p)-s;
}
vec3 RotX (vec3 p, float speed)
{
return vec3(p.x, p.y*cos(speed) + p.z*-sin(speed),  p.y*sin(speed) + p.z*cos(speed));
}
vec3 RotY (vec3 p, float speed)
{
return vec3(p.x*cos(speed) + p.z*sin(speed), p.y, p.x*-sin(speed) + p.z*cos(speed));
}
vec3 RotZ (vec3 p, float speed)
{
return vec3(p.x*cos(speed)  + p.y*-sin(speed), p.x*sin(speed) + p.y*cos(speed), p.z);
}
vec3 GetTorus1Pos()
{
vec3 pos = torus1Pos;
//pos = RotY(torus1Pos, uTime * 2.0);
return pos;
}
float smin( float a, float b, float k )
{
float h = clamp(0.5 + 0.5*(b-a)/k, 0.0 , 1.0 );
return mix(b, a, h) - k*h*(1.0 - h);
}
vec2 GetDist(vec3 p)
{
float groundDist = p.y;
float groundID = 1;
// torus 1
vec3 torusPosNew = RotY(p - torus1Pos, uTime);
vec3 pNew = RotY(p, q26*1.5);
float torusDist = sdTorus1(pNew - torus1Pos, torus1Size);
float torusID = 2;
// torus 2
//float torus2Dist = sdTorus2(p - torus2Pos, torus2Size);
//float torus2ID = 2.1;
// sphere
float sphereDist = sdSphere(p - spherePos, sphereRad);
float sphereID = 3;
float shape = min(groundDist, torusDist);
//shape = min(shape, torus2Dist);
shape = min(shape, sphereDist);
vec2 toreturn;
if(shape == groundDist)
toreturn = vec2(groundDist, groundID);
if(shape == torusDist)
toreturn = vec2(torusDist, torusID);
if(shape == sphereDist)
toreturn = vec2(sphereDist, sphereID);
return toreturn;
}
vec3 RayMarch(vec3 ro, vec3 rd, float steps)
{
vec2 dS;
float dO;
vec3 p;
float breakloop = 0;
for(int i = 0; i<steps && breakloop == 0; i++)
{
p = ro + rd * dO;
dS = GetDist(p);
if(dS.x < 0.0001) {breakloop = 1; }
dO += dS.x*0.5;
}
return vec3(dO,dS);
}
float dist(vec2 a, vec2 b)
{
return sqrt(pow(a.x-b.x, 2.0 ) + pow(a.y-b.y, 2.0 ));
}
float fract(float a)
{
return(a - floor(a));
}
vec2 fract(vec2 a)
{
vec2 b = vec2(fract(a.x), fract(a.y));
return b;
}
float Hash21(vec2 p)
{
p = fract(p * vec2(234.34, 435.345) );
p += dot(p, p + 34.24);
return fract(p.x*p.y);
}
vec3 SpaceGif(vec2 UV)
{
//UV-= 0.5;
//UV.y*=-1;
//UV *= uAspect.xy;
UV.x += 0.285;
UV.y += 0.26;
//   float t = uTime;
vec3 col = vec3( 0.0 , 0.0 , 0.0 );
UV *= 1.8;
vec2 gv = fract(UV) - 0.5;
vec2 id = floor(UV);
float m = 0;
for(int y = -1; y <= 1; y++)
{
for(int x = -1; x <= 1; x++)
{
vec2 offs = vec2(x,y);
float d = length(gv - offs);
float dist = length(id+offs)*0.9;
float r = 0.51 + 0.5*sin(dist - 5.0*q26 - 0.0*0.2*q6 - uTime * 1.0);
float c = smoothstep(r, r*0.05, d);
m = m*(1.0 - c) + c*(1.0 - m);
}
}
//col.xy = gv.xy;
//col += vec3(m, 0.0 ,m*0.5);
//col.y = smoothstep(-1, 1.0 , sin(uTime + 0.05*UV.y*UV.x));
//col.x = smoothstep(-1, 1.0 , cos(uTime + 0.05*UV.y*UV.x));
//col.z = 0.5 + 0.5*cos(uTime);
col = vec3( 2.0 , 1.0 ,0.7);
col *= m;
return col;
}
vec3 toruscol(vec3 p, vec3 tpos, vec2 tsize, float rotspeed)
{
//vec3 col = 0;
float x = atan(p.x + tpos.x, p.z + tpos.z);
float y = atan(length(p.xz + tpos.xz)-tsize.x, p.y + tpos.y);
float speed = uTime * 15.0;
//vec3 a = stars(vec2(x,y), 0.0 * uTime);
//float f1 = sin(x * 25.0)*sin(y * 50.0+speed);
//f1 = smoothstep( 0.0 , 0.001, f1);
float f1 = smoothstep(0.4, 0.5, 0.5 + 0.5*cos(y*(30.0 * sin(q26*0.5)) + x*(15 + 0*5*sin(uTime*0.5 + q6*0.05))));
//            * smoothstep( 0.0 , 0.5, sin(y*(55 + 35.0 * sin(q26)) + uTime * 20.0*0 + q26 * 40.0 + 0.0 * q5*2.5));
float f2 = smoothstep(0.4, 0.5, 0.5 + 0.5*sin(y*(30.0 * cos(q26*0.5)) + x*(15 + 0*5*cos(uTime*0.5 + q6*0.05))));
vec3 col1 = f1*f2*vec3(1 + 60.0 * q2, 1.0 , 1.0 );
vec3 col2 = f1*f2*vec3(1 + 60.0 * q2, 1.0 , 1.0 );
return col1; // + SpaceGif(abs(vec2(x,y)) * 10.0);
}
vec3 GetNormal(vec3 p)
{
float d = GetDist(p).x;
vec2 e = vec2(.01, 0.0 );
vec3 n = d-vec3(GetDist(p-e.xyy).x,
GetDist(p-e.yxy).x,
GetDist(p-e.yyx).x);
return normalize(n);
}
float GetLight(vec3 p, vec3 n, vec3 lightpos, float lightpower, float shadowstrength, float steps)
{
//vec3 lightpos = LightPos;
//lightpos = camerapos;
vec3 l = normalize(lightpos - p);
//vec3 n = GetNormal(p);
float dif = clamp(dot(n, l*lightpower), 0., 1.);
//dif = dot(n,l);
//float d = RayMarch(p + n*0.2, l, steps);
//if(d < length(lightpos-p)) {dif *= shadowstrength;}
return dif;
}
float HexDist(vec2 p) {
p = abs(p);
float c = dot(p, normalize(vec2( 1.0 ,1.73)));
c = max(c, p.x);
return c;
}
vec4 HexCoords(vec2 UV)
{
vec2 r = vec2( 1.0 , 1.73);
vec2 h = r*.5;
vec2 a = (UV%r)-h;//mod(UV, r)-h;
vec2 b = ((UV-h)%r)-h;//mod(UV-h, r)-h;
vec2 gv = dot(a, a) < dot(b,b) ? a : b;
float x = atan(gv.x, gv.y);
float y = .5-HexDist(gv);
vec2 id = UV-gv;
return vec4(x, y, id.x,id.y);
}
vec3 Hive(vec2 UV, float mul, float add)
{
vec3 col = 0;
UV *= mul;
vec4 hc = HexCoords(UV + add);
float c = smoothstep(.01, 0.03, hc.y*1.4  + 2.4*hc.y*sin(hc.z*hc.w+q5*0.1 + 1.5*q26)*cos(hc.z*hc.w+q5*0.1 + 1.5*q26));
float c2 = smoothstep(0.01, 0.2, hc.y * 0.0  + hc.y*sin(hc.z*hc.w+q6*0.1 + 1.5*uTime)*cos(hc.z*hc.w+q6*0.1 + 1.5*uTime));
float c3 = smoothstep(0.01, 0.6, hc.y * 0.0  + hc.y*sin(hc.z*hc.w+q7*0.1 + 1.5*uTime)*cos(hc.z*hc.w+q7*0.1 + 1.5*uTime));
col = (1.0 - c)*normalize(vec3( 1.0 , 1.0 ,0.3))*1.5;
col += c2*normalize(vec3( 3.0 ,1.4, 0.0 ));
col += c3*normalize(vec3( 4.0 ,1.4, 0.0 ));
//return c;
return col * 2.0;
}
vec3 sphereCol(vec3 p, vec3 spPos, float r)
{
vec3 n = normalize(p-r);
float x = atan(n.x, n.z)/(2.0 * PI) + 0.5;
float y = 0.5 + 0.5*n.y;
vec3 col = 1.0 - Hive(vec2(x,y*0.5), 50.0 , 0.0 );
return col;
}
float specularReflection(vec3 p, vec3 N, vec3 rd, vec3 lightPos, float intensity, float shininessVal)
{
//vec3 N = GetNormal(p);
vec3 L = normalize(lightPos - p);
float lambertian = max(dot(L, N), 0.0);
float specular = 0.;
if(lambertian > 0.0) {
vec3 R = reflect(-L, N);      // Reflected light vector
vec3 V = normalize(-rd); // Vector to viewer
// Compute the specular term
float specAngle = max(dot(R, V), 0.0);
specular = pow(specAngle, shininessVal);
}
return specular * intensity;
}
float calcOcclusion(vec3 p, vec3 n)
{
float occ = 0.0;
float sca = 1.0;
for( int i=0; i<10; i++ )
{
float h = 0.01 + 0.11*i/4.0;
vec3 opos = p + h*n;
float d = GetDist(opos);
occ += (h-d)*sca;
//sca *= 0.95;
}
return clamp( 1.0 - 2.0*occ, 0.0, 1.0 );
}
vec3 applyFog( in vec3  rgb,      // original color of the pixel
in float distance, // camera to point distance
in vec3  rayDir,   // camera to point vector
in vec3  sunDir,   // sun light direction
in float strength)
{
float fogAmount = 1.0 - exp( -distance*strength );
float sunAmount = max( dot( rayDir, sunDir ), 0.0 );
vec3  fogColor  = mix( mix(vec3(1.2,0.7,0.4)*1., vec3(0.3,0.7,1.), sunDir.y),
vec3(1.,0.9,0.7)*1.5, // yellowish
pow(sunAmount,20.) );
return mix( rgb, fogColor, fogAmount );
}
vec3 applyFog( vec3 rgb, float distance, float strength)
{
float fogAmount = 1.0 - exp( -distance*strength );
vec3 fogColor = vec3(q3, q1, q2);//vec3(1., 0.3, 0.8);
return mix( rgb, fogColor, fogAmount );
}
