vec3 Get1 (vec2 uvi, float par)
{return mix(GetBlur1(uvi), GetPixel(uvi), 0.0 * clamp01(par / 2.0))*par;}
ret += max(shine,0.0 * GetPixel(uv));
//ret = shine+GetPixel(uv);
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  float sunx =  q31*0.5 +0.55, suny = q32*0.5 + 0.34;
