vec3 RayMarch(vec3 ro, vec3 rd, float steps)
{
vec2 dS;
float dO;
vec3 p;
float breakloop = 0;
for(int i = 0; i<steps && breakloop == 0; i++)
{
p = ro + rd * dO;
dS = GetDist(p);
if(dS.x < 0.0001) {breakloop = 1; }
dO += dS.x*0.5;
}
return vec3(dO,dS);
}
