float HexDist(vec2 p) {
p = abs(p);
float c = dot(p, normalize(vec2( 1.0 ,1.73)));
c = max(c, p.x);
return c;
}
vec4 HexCoords(vec2 UV)
{
vec2 r = vec2( 1.0 , 1.73);
vec2 h = r*.5;
vec2 a = (UV%r)-h;//mod(UV, r)-h;
vec2 b = ((UV-h)%r)-h;//mod(UV-h, r)-h;
vec2 gv = dot(a, a) < dot(b,b) ? a : b;
float x = atan(gv.x, gv.y);
float y = .5-HexDist(gv);
vec2 id = UV-gv;
return vec4(x, y, id.x,id.y);
}
vec3 Hive(vec2 UV, float mul, float add)
{
vec3 col = 0;
UV *= mul;
vec4 hc = HexCoords(UV + add);
float c = smoothstep(.01, 0.03, hc.y*1.4  + 2.4*hc.y*sin(hc.z*hc.w+q5*0.1 + 1.5*q26)*cos(hc.z*hc.w+q5*0.1 + 1.5*q26));
float c2 = smoothstep(0.01, 0.2, hc.y * 0.0  + hc.y*sin(hc.z*hc.w+q6*0.1 + 1.5*uTime)*cos(hc.z*hc.w+q6*0.1 + 1.5*uTime));
float c3 = smoothstep(0.01, 0.6, hc.y * 0.0  + hc.y*sin(hc.z*hc.w+q7*0.1 + 1.5*uTime)*cos(hc.z*hc.w+q7*0.1 + 1.5*uTime));
col = (1.0 - c)*normalize(vec3( 1.0 , 1.0 ,0.3))*1.5;
col += c2*normalize(vec3( 3.0 ,1.4, 0.0 ));
col += c3*normalize(vec3( 4.0 ,1.4, 0.0 ));
//return c;
return col * 2.0;
}
vec3 sphereCol(vec3 p, vec3 spPos, float r)
{
vec3 n = normalize(p-r);
float x = atan(n.x, n.z)/(2.0 * PI) + 0.5;
float y = 0.5 + 0.5*n.y;
vec3 col = 1.0 - Hive(vec2(x,y*0.5), 50.0 , 0.0 );
return col;
}
float specularReflection(vec3 p, vec3 N, vec3 rd, vec3 lightPos, float intensity, float shininessVal)
{
//vec3 N = GetNormal(p);
vec3 L = normalize(lightPos - p);
float lambertian = max(dot(L, N), 0.0);
float specular = 0.;
if(lambertian > 0.0) {
vec3 R = reflect(-L, N);      // Reflected light vector
vec3 V = normalize(-rd); // Vector to viewer
// Compute the specular term
float specAngle = max(dot(R, V), 0.0);
specular = pow(specAngle, shininessVal);
}
return specular * intensity;
}
float calcOcclusion(vec3 p, vec3 n)
{
float occ = 0.0;
float sca = 1.0;
for( int i=0; i<10; i++ )
{
float h = 0.01 + 0.11*i/4.0;
vec3 opos = p + h*n;
float d = GetDist(opos);
occ += (h-d)*sca;
//sca *= 0.95;
}
return clamp( 1.0 - 2.0*occ, 0.0, 1.0 );
}
vec3 applyFog( in vec3  rgb,      // original color of the pixel
in float distance, // camera to point distance
in vec3  rayDir,   // camera to point vector
in vec3  sunDir,   // sun light direction
in float strength)
{
float fogAmount = 1.0 - exp( -distance*strength );
float sunAmount = max( dot( rayDir, sunDir ), 0.0 );
vec3  fogColor  = mix( mix(vec3(1.2,0.7,0.4)*1., vec3(0.3,0.7,1.), sunDir.y),
vec3(1.,0.9,0.7)*1.5, // yellowish
pow(sunAmount,20.) );
return mix( rgb, fogColor, fogAmount );
}
vec3 applyFog( vec3 rgb, float distance, float strength)
{
float fogAmount = 1.0 - exp( -distance*strength );
vec3 fogColor = vec3(q3, q1, q2);//vec3(1., 0.3, 0.8);
return mix( rgb, fogColor, fogAmount );
}
