vec2 GetShapes(vec3 p) { return (1.7*sin(uTime*0.2 + q26*0.4))*sin(2.0 * p.xz)
+ (q27*0.1)*sin(7.0 * p.zx + q26 * 5.0).xy; }
float sdTorus1(vec3 p, vec2 r) {
float x = length(p.xz + GetShapes(p) )-r.x;
