vec2 sunpos = vec2(0.5,0.5);
uva = (uv-0.5)*uAspect.xy+0.5;
float sun = (.01 / length (uva-sunpos));
dz.x = lum(GetPixel(uv-hor)) - lum(GetPixel(uv+hor).xy);
dz.y = lum(GetPixel(uv-ver)) - lum(GetPixel(uv+ver).xy);
vec3 shine = GetPixel(uv);
